        { !!device && <>
            <DeviceTile
                device={device}
            >
                <DeviceExpandDetailsButton
                    data-testid='current-session-toggle-details'
                    isExpanded={isExpanded}
                    onClick={() => setIsExpanded(!isExpanded)}
                />
